<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import PageHead from '@/components/PageHead.vue'
import CoomiIcon from '@/components/CoomiIcon.vue'
import { apiGet, apiSend } from '@/bridge/http'
import { goBack } from '@/bridge/navigation'
import { useConfigStore } from '@/stores/config'

interface Member { id:string; name:string; modelSelector:string; prompt:string; color?:string; quota:number }
interface Room { id:string; name:string; topic:string; status:string; speakMode:string; memberCount:number; preview:string; messageCount:number; updatedAtMs:number }
const router=useRouter(),config=useConfigStore();const rooms=ref<Room[]>([]),loading=ref(false),error=ref(''),open=ref(false),saving=ref(false)
const name=ref(''),topic=ref(''),workDir=ref('/workspace'),speakMode=ref('round_robin'),members=ref<Member[]>([])
const models=computed(()=>config.providers.filter(p=>p.hasKey).flatMap(p=>p.models.map(m=>({value:`${p.id}:${m}`,label:`${p.name} · ${m}`}))))
function addMember(){const n=members.value.length+1;members.value.push({id:`member_${Date.now()}_${n}`,name:`成员 ${n}`,modelSelector:models.value[0]?.value??'',prompt:'负责独立分析，并与其他成员协作。',quota:0})}
function removeMember(id:string){members.value=members.value.filter(m=>m.id!==id)}
async function load(){loading.value=true;try{await config.fetchProviders();rooms.value=(await apiGet<{rooms:Room[]}>('/api/group-chat/rooms')).rooms??[];error.value=''}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}
async function create(){if(!name.value.trim()||members.value.length<1)return;saving.value=true;try{const room=await apiSend<{id:string}>('/api/group-chat/rooms','POST',{name:name.value.trim(),topic:topic.value.trim(),workDir:workDir.value,speakMode:speakMode.value,members:members.value});open.value=false;await router.push(`/im/${room.id}`)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{saving.value=false}}
function begin(){name.value='';topic.value='';workDir.value='/workspace';speakMode.value='round_robin';members.value=[];addMember();addMember();open.value=true}
onMounted(load)
</script>
<template><div class="page"><PageHead title="我的 AI 工作台" @back="goBack(router,'dashboard')"><template #right><button class="icon" @click="begin"><CoomiIcon name="plus"/></button></template></PageHead><main class="body"><p v-if="error" class="notice">{{error}}</p><p v-if="loading" class="hint">同步工作台中…</p><section v-else-if="!rooms.length" class="empty"><span><CoomiIcon name="team" :size="30"/></span><b>组建你的 AI 团队</b><p>配置成员、模型与发言方式，在同一个房间里协作。</p><button @click="begin">创建工作台</button></section><section v-else class="cards"><button v-for="r in rooms" :key="r.id" class="card" @click="router.push(`/im/${r.id}`)"><div class="head"><span><CoomiIcon name="team"/></span><b>{{r.name}}</b><em :class="r.status">{{r.status==='running'?'运行中':'待命'}}</em></div><p>{{r.preview||r.topic||'还没有消息'}}</p><footer><span>{{r.memberCount}} 位成员</span><span>{{r.messageCount}} 条消息</span><CoomiIcon name="chevronRight" :size="14"/></footer></button></section></main><div v-if="open" class="mask" @click.self="open=false"><section class="sheet"><i/><h3>创建 AI 工作台</h3><label>名称<input v-model="name" placeholder="例如：产品研发组"/></label><label>协作话题<textarea v-model="topic" rows="2" placeholder="团队长期目标和讨论范围"/></label><div class="grid"><label>发言方式<select v-model="speakMode"><option value="round_robin">轮流发言</option><option value="open">全员并行</option><option value="host">主持人指定</option></select></label><label>工作目录<input v-model="workDir"/></label></div><div class="sec"><b>成员（{{members.length}}）</b><button @click="addMember"><CoomiIcon name="plus" :size="13"/>添加</button></div><article v-for="m in members" :key="m.id" class="member"><div><input v-model="m.name"/><button @click="removeMember(m.id)"><CoomiIcon name="trash" :size="14"/></button></div><select v-model="m.modelSelector"><option value="">跟随默认模型</option><option v-for="o in models" :key="o.value" :value="o.value">{{o.label}}</option></select><textarea v-model="m.prompt" rows="2"/><label class="quota">发言配额（0 为不限）<input v-model.number="m.quota" type="number" min="0"/></label></article><footer class="acts"><button @click="open=false">取消</button><button class="primary" :disabled="saving||!name.trim()||!members.length" @click="create">{{saving?'创建中…':'创建并进入'}}</button></footer></section></div></div></template>
<style scoped>.page{height:100%;display:flex;flex-direction:column;background:var(--page)}.body{flex:1;overflow:auto;padding:12px 12px calc(var(--safe-bottom) + 24px)}.icon{width:44px;height:44px;color:var(--blue)}.notice{padding:10px;border-radius:var(--r-md);background:var(--danger-soft);color:var(--danger)}.hint{text-align:center;color:var(--text-3)}.empty{display:flex;flex-direction:column;align-items:center;text-align:center;padding:48px 20px;color:var(--text-3)}.empty>span{display:grid;place-items:center;width:62px;height:62px;border-radius:20px;background:var(--blue-soft);color:var(--blue)}.empty b{margin-top:12px;color:var(--text);font-size:16px}.empty p{font-size:12.5px;line-height:1.6}.empty button,.primary{min-height:44px;padding:0 18px;border-radius:var(--r-md);background:var(--blue);color:white}.cards{display:grid;gap:10px}.card{padding:13px;border:1px solid var(--border);border-radius:var(--r-card);background:var(--bg);text-align:left;animation:coomi-cascade .2s ease both}.head{display:flex;align-items:center;gap:9px}.head>span{display:grid;place-items:center;width:36px;height:36px;border-radius:11px;background:var(--blue-soft);color:var(--blue)}.head b{flex:1;color:var(--text)}.head em{font-style:normal;font-size:10px;color:var(--text-3)}.head em.running{color:var(--blue);animation:pulse 1.2s ease-in-out infinite}.card p{color:var(--text-2);font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.card footer{display:flex;gap:12px;color:var(--text-3);font-size:11px}.card footer svg{margin-left:auto}.mask{position:fixed;inset:0;z-index:80;display:flex;align-items:flex-end;background:rgba(0,0,0,.4)}.sheet{width:100%;max-height:90vh;overflow:auto;padding:8px 14px calc(var(--safe-bottom) + 15px);border-radius:22px 22px 0 0;background:var(--bg);animation:rise .24s cubic-bezier(.22,.68,.19,1)}.sheet>i{display:block;width:38px;height:4px;margin:2px auto 12px;border-radius:2px;background:var(--border)}h3{margin:0 0 12px;color:var(--text)}label{display:block;margin:9px 0;color:var(--text-3);font-size:11px}input,textarea,select{width:100%;min-height:40px;margin-top:4px;padding:8px 10px;border:1px solid var(--border);border-radius:var(--r-md);background:var(--fill);color:var(--text)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.sec{display:flex;align-items:center;justify-content:space-between;margin:14px 0 7px}.sec button{display:flex;gap:4px;color:var(--blue)}.member{margin-bottom:8px;padding:10px;border-radius:var(--r-md);background:var(--fill)}.member>div{display:flex;gap:6px}.member>div input{margin:0}.member>div button{width:40px;color:var(--danger)}.quota{display:flex;align-items:center;gap:8px}.quota input{width:70px;margin-left:auto}.acts{display:flex;gap:8px;margin-top:14px}.acts button{flex:1;min-height:44px;border-radius:var(--r-md);background:var(--fill-strong);color:var(--text-2)}.acts .primary{background:var(--blue);color:white}@keyframes rise{from{transform:translateY(100%)}to{transform:none}}@keyframes pulse{50%{opacity:.35}}</style>
